#include <vector>
#include <iostream>

int main() {
    std::vector<int> v = {10, 20};
    // Assume capacity is 2
    const int* p = &v[0];

    v.push_back(30); // May trigger reallocation

    // Check if the address of the first element changed
    if (p != &v[0]) {
        std::cout << "Iterator/Reference invalidated!\n";
    } else {
        std::cout << "No invalidation (capacity was sufficient).\n";
    }

    // In contrast, list iterators are stable:
    // std::list<int> l = {1, 2};
    // auto it = l.begin();
    // l.push_back(3);
    // *it is still valid.
}
